import { Helper, Color } from './lib/helper'
import { depValue } from 'ts-dep'

class Adapter {
  #secret = 42
  constructor(private readonly name: string) {}
  get info(): string {
    return `${this.name}:${this.#secret}`
  }
}

const a = new Adapter('demo')
console.log([a.info, Color[Color.Green], new Helper().greet(), depValue].join('|'))
